from collate import *
import difflib
src=parse()
da=read('upstream/modern-da.json'); en=read('upstream/modern-en.json')
original=read('upstream/original-en.json')['chapters']
assert len(src)==len(original)==len(da['chapters'])==len(en['chapters'])==365
records=[]
def fix(lang,c,p,text,reason):
 ed={'da':da,'en':en}[lang]['chapters'][c-1]
 if p==0:old=ed['title'];ed['title']=text
 else:old=ed['paragraphs'][p-1];ed['paragraphs'][p-1]=text
 if text!=old:records.append(dict(language=lang,chapter=c,paragraph=p or None,before=old,after=text,reason=reason))
def d(c,p,text):fix('da',c,p,text,'Restore the scene, argument or register from Maude.')
def e(c,p,text):fix('en',c,p,text,'Correct a discrepancy with the complete source.')
def add(c,p,text):d(c,p,da['chapters'][c-1]['paragraphs'][p-1]+' '+text)
def modern(c,p):return en['chapters'][c-1]['paragraphs'][p-1]
def source(c,p):return original[c-1]['paragraphs'][p-1]
ordinals='Første Anden Tredje Fjerde Femte Sjette Syvende Ottende Niende Tiende Ellevte Tolvte Trettende Fjortende Femtende'.split()
for i,(b,h,ps) in enumerate(src):
 a=original[i];assert ps==[' '.join(p.split()) for p in a['paragraphs']]
 assert len(ps)==len(da['chapters'][i]['paragraphs'])==len(en['chapters'][i]['paragraphs'])
 if i==0 or b!=src[i-1][0]:sub=1
 else:sub+=1
 bookidx=list(dict.fromkeys(s[0] for s in src)).index(b)
 title=(ordinals[bookidx]+' bog' if bookidx<15 else ('Første','Anden')[bookidx-15]+' epilog')
 if ':' in b:title+=' ('+b.split(': ')[1].replace(' - ','–')+')'
 fix('da',i+1,0,title+' — Kapitel '+str(sub),'Match section and chapter number in Maude.')
d(1,1,'[På fransk] »Nå, fyrste, så nu er Genova og Lucca blevet familiegodser for Bonaparterne! Men jeg advarer Dem. Hvis De ikke siger, at det betyder krig, hvis De stadig vil forsvare den Antikrists skændselsgerninger og rædsler – ja, jeg tror virkelig, han er Antikrist – så vil jeg ikke have mere med Dem at gøre. Så er De ikke længere min ven, ikke længere min ‘trofaste slave’, som De selv kalder Dem! Men hvordan har De det? Jeg kan se, jeg har forskrækket Dem. Sæt Dem ned og fortæl mig alt, hvad der er sket.«')
d(1,2,'Det var i juli 1805. Den talende var den velkendte Anna Pavlovna Scherer, hofdame hos kejserinde Marja Fjodorovna og en af hendes yndlinge. Med de ord tog hun imod fyrst Vasilij Kuragin, en mand af høj rang og stor indflydelse, som kom først af gæsterne den aften. Anna Pavlovna havde hostet i flere dage. Hun havde, som hun selv sagde, la grippe. Grippe var dengang et nyt ord i Sankt Petersborg, og kun det fine selskab brugte det.')
d(226,3,'For hvert nyt nedslag svandt udsigten til at slippe levende derfra for dem, der endnu var i live. Regimentets bataljoner stod i kolonner med tre hundrede skridts mellemrum, men stemningen var den samme overalt. Alle var tavse og mørke. Kun sjældent talte nogen i geledderne, og hver gang de hørte det dumpe stød af en kugle, der ramte, og råbet: »Bårer!«, forstummede samtalen helt. Det meste af tiden sad soldaterne på jorden efter officerernes ordre. En havde taget sin chakot af og sad omhyggeligt og løsnede rynkerne i foret og trak dem til igen. En anden gned tørt ler mellem håndfladerne og pudsede sin bajonet med det. En tredje pillede ved remmen og trak i spændet på sit bandoler. En fjerde glattede sine benvikler, lagde dem om på ny og trak støvlerne på. Nogle byggede små huse af jordknolde fra pløjemarken eller flettede kurve af strå ude i kornet. Alle så ud til at gå helt op i deres gøremål. At mænd faldt døde eller sårede om, at båre efter båre blev båret forbi, at tropper trak sig tilbage, at store fjendtlige styrker kom til syne gennem røgen, det ænsede ingen. Men rykkede vores artilleri eller kavaleri frem, eller så de noget af vores infanteri gå frem, lød der opmuntrende tilråb fra alle sider. Det, der vakte den livligste interesse, var dog ting, som slet ingen forbindelse havde med slaget. Det var, som om disse mænd var så udslidte på sjælen, at de fandt lindring i det mest dagligdags. Et batteri kørte forbi foran regimentet. En af hestene for en ammunitionsvogn fik benet over skaglen. »Hov, se lige den hest! Få benet fri! Nu falder den … Åh, de ser det ikke!« Nøjagtig de samme råb lød langs hele regimentets front. En anden gang samlede al interesse sig om en lille brun hund, der kom, Gud ved hvorfra, og travede forbi geledderne, optaget af sit eget og med halen stift i vejret. Pludselig slog en granat ned lige ved siden af den. Hunden gav et hyl, stak halen mellem benene og fór til siden. Hele regimentet skreg af grin. Men det var kun et øjebliks adspredelse. I otte timer havde mændene siddet uvirksomme, uden mad og i stadig dødsangst, og deres blege, dystre ansigter blev blegere og dystrere.')
e(226,3,modern(226,3).replace('when rows of stretchers passed, or','when rows of stretchers passed, when troops fell back, or'))
add(344,4,'Det vigtigste var i hans øjne hverken kvælstoffet i jorden eller ilten i luften, hverken gødningen eller de særlige plove. Det vigtigste var den, der fik kvælstoffet og ilten, gødningen og ploven til at virke: bonden, der gjorde arbejdet. Da Nikolaj først tog fat på driften og begyndte at forstå de forskellige sider af den, var det især den livegne bonde, der optog ham. I bonden så han både et redskab, en mand, der selv kunne bedømme driften, og et mål i sig selv. I begyndelsen iagttog han bønderne og prøvede at forstå, hvad de ville, og hvad de selv fandt godt eller skidt. Han lod, som om han ledede arbejdet og gav ordrer, mens det i virkeligheden var ham, der lærte af dem: hvordan de bar sig ad, hvordan de talte, og hvordan de skelnede mellem godt og skidt. Først da han kendte deres smag og ønsker, kunne tale deres sprog og høre, hvad der lå bag ordene, og følte sig beslægtet med dem, tog han med fast hånd fat på at lede sine livegne, det vil sige gøre sin pligt over for dem. Og Nikolaj opnåede glimrende resultater.')
e(344,4,modern(344,4).replace('or expensive crops','in growing expensive crops or buying costly seed grain')+" And Nicholas’s management brought splendid results.")
d(350,6,'Den slags samtaler, som ingen interesserer sig for, og som man alligevel må igennem, fortsatte, så længe de drak te. Alle familiens voksne var samlet omkring det runde tebord, hvor Sonja rådede ved samovaren. Børnene havde drukket te med deres huslærere og guvernanter, og inde ved siden af kunne man høre deres stemmer. Alle havde deres faste pladser. Nikolaj fik teen bragt hen til sit lille bord ved ovnen. På lænestolen ved siden af ham lå Milka, den gamle grå mynde, datter af den første Milka. Snuden var blevet helt grå, og de store sorte øjne syntes at træde mere frem end nogensinde. Denisov, hvis krøller, overskæg og bakkenbarter var halvt grå, sad ved siden af grevinde Marja med generalsjakken knappet op. Pierre sad mellem sin kone og den gamle grevinde. Han talte om det, han vidste hun kunne følge med i og ville høre om: nyt ude fra selskabslivet og nyt om dem, der hørte til hendes egen kreds. Engang havde de udgjort en virkelig, levende, klart afgrænset kreds. Nu var de fleste spredt for alle vinde og samlede som hun de sidste aks af det, de havde sået i yngre år. Men for den gamle grevinde var disse jævnaldrende stadig de eneste mennesker, der for alvor talte. På Pierres iver kunne Natasja se, at hans rejse havde været interessant. Han havde meget at fortælle, som han ikke turde sige i den gamle grevindes påhør. Denisov hørte ikke til familien og forstod ikke, hvorfor Pierre holdt sig tilbage. Som den utilfredse mand han var, fulgte han ivrigt med i alt, hvad der skete i Petersborg. Han blev ved med at presse Pierre: Hvad var der sket i Semjonovskijregimentet? Og hvad med Araktjejev? Og Bibelselskabet? Et par gange lod Pierre sig rive med og begyndte at fortælle, men Nikolaj og Natasja fik ham hver gang tilbage til fyrst Ivans og grevinde Marja Aleksejevnas helbred.')
e(350,6,'The talk went on through tea, of the kind that interests nobody and can never be avoided. All the grown-ups were gathered around the round tea table, where Sonya presided over the samovar. The children had had their tea with their tutors and governesses, and their voices carried in from the next room. Everyone had a usual place. Nicholas took his tea at a little table beside the stove. On the armchair next to him lay Milka, the old gray borzoi, daughter of the first Milka. Her face was quite gray now and her large black eyes seemed to stand out more than ever. Denisov, his curls, mustache and whiskers half gray, sat next to Countess Mary with his general’s tunic unbuttoned. Pierre sat between his wife and the old countess. He spoke of things he knew the old lady could follow and would like to hear. He brought news of society and of her own circle, once a real, living, distinct company of people, most of them now scattered over the world and gathering, like her, the last ears of the harvests they had sown in younger days. Yet to the old countess these contemporaries of hers were the only society that was serious or real. Natasha could tell by Pierre’s animation that his visit had been interesting and he had plenty to say, but daren’t say it in front of the old countess. Denisov, outside the family, missed the reason for his caution. As a discontented man himself he took a keen interest in what was happening in Petersburg and kept pressing Pierre about the Semyonovsky regiment, then Arakcheyev, then the Bible Society. Once or twice Pierre got carried away and began to tell them, but Nicholas and Natasha always steered him back to the health of Prince Ivan and Countess Mary Alexeyevna.')
add(220,14,'Snart syntes røgskyerne at fare af sted, snart stod de stille, mens skovene, markerne og de blinkende bajonetter strøg forbi. Til venstre, ude over marker og krat, blev de store røgkugler ved med at dukke op, og efter hver fulgte et højtideligt drøn. Nærmere på, i lavningerne og i skoven, slog små røgpust ud af musketterne. De fik ikke tid til at samle sig til kugler, men hvert pust havde sit eget lille ekko. »Trak-ta-ta-tak!« Musketilden knitrede tæt, men ujævnt og spinkelt ved siden af kanonernes drøn.')
add(217,28,'Ikke en eneste ordre i slagplanen blev altså udført eller kunne være blevet det. Nu står der ganske vist i planen, at så snart kampen er indledt på denne måde, vil der blive givet ordrer efter fjendens bevægelser. Man kunne da tro, at Napoleon under slaget ville træffe alle de nødvendige forholdsregler. Men det gjorde han ikke og kunne han ikke gøre. Under hele slaget var han så langt borte, at han, som det senere viste sig, umuligt kunne vide, hvordan det gik, og ikke én af hans ordrer under kampen lod sig udføre.')
d(347,17,'At Pierre var under tøflen, bestod i, at han ikke turde flirte med andre kvinder, ja, han turde ikke engang smile til dem, når han talte med dem. Han turde ikke spise i klubben for sin fornøjelses skyld, ikke bruge penge på et indfald og ikke være længe borte fra hjemmet, medmindre han havde noget at udrette. Dertil regnede hans kone også hans åndsarbejde, som hun ikke forstod det mindste af, men tillagde stor betydning. Til gengæld havde Pierre hjemme ret til at indrette både sit eget og hele familiens liv ganske efter sit hoved. Hjemme gjorde Natasja sig til sin mands slavinde. Hele huset gik på tåspidser, når han arbejdede, det vil sige sad i sit værelse og læste eller skrev. Pierre behøvede blot at vise, at han foretrak noget, så blev det altid gjort, som han helst ville have det. Han behøvede blot at ytre et ønske, så sprang Natasja op og løb hen for at opfylde det.')
add(230,16,'Jeg ser kun begivenheder falde sammen, som det sker med alle livets fænomener. Og hvor længe og hvor nøje jeg end iagttager urets visere, maskinens ventiler og hjul eller knopperne på egen, finder jeg ikke ud af, hvad der får klokkerne til at ringe, maskinen til at gå eller forårsvinden til at blæse. Skal jeg finde det, må jeg se sagen fra en helt anden side og undersøge lovene for dampens, klokkernes og vindens bevægelser. Historien må gøre det samme. Og man har allerede gjort forsøg i den retning.')
add(223,10,'Således kom en adjudant i galop fra Murat med melding om, at Borodino var taget, og at broen over Kolotsja var i franskmændenes hænder. Ønskede Napoleon, at tropperne skulle gå over? Napoleon gav ordre til, at de skulle tage opstilling på den anden side og vente. Men før han gav ordren – ja, næsten lige så snart adjudanten havde forladt Borodino – havde russerne generobret broen og brændt den. Det var netop den træfning, Pierre havde overværet ved slagets begyndelse.')
d(223,12,'Marskallerne og generalerne var tættere på slagmarken, men ligesom Napoleon deltog de ikke selv i kampen og kom kun af og til inden for musketskudsvidde. De traf deres egne beslutninger uden at spørge ham og gav ordre om, hvor der skulle skydes fra og i hvilken retning, hvor rytterne skulle galopere hen, og hvor fodfolket skulle løbe. Men deres ordrer blev ligesom Napoleons sjældent fulgt, og da kun halvt. Som regel gik det stik imod ordren. Soldater, der skulle rykke frem, løb tilbage, når de fik kardæskild imod sig. Soldater, der skulle blive stående, fik pludselig øje på russere lige foran sig og styrtede snart tilbage, snart frem. Rytteriet satte uden ordre efter flygtende russere. To kavaleriregimenter galoperede således gennem lavningen ved Semjonovskoje, og da de nåede bakkekammen, vendte de om og galoperede tilbage i fuldt firspring. På samme måde løb fodfolket undertiden helt andre steder hen, end der var givet ordre til. Hvor og hvornår kanonerne skulle flyttes, hvornår fodfolket skulle sendes frem for at skyde, eller rytterne for at ride det russiske infanteri ned – alle den slags ordrer gav de officerer, der var nærmest de pågældende tropper, uden at spørge hverken Ney, Davout eller Murat, endsige Napoleon. De frygtede ingen straf for at handle på egen hånd eller sidde en ordre overhørig. I kamp gælder det jo det dyrebareste, et menneske har, selve livet, og snart synes redningen at ligge i at løbe tilbage, snart i at løbe frem. Mændene midt i kampens hede handlede, som øjeblikket indgav dem. I virkeligheden blev troppernes stilling hverken bedre eller anderledes af al den renden frem og tilbage. At de løb og red løs på hinanden, gjorde kun ringe skade. Det, der lemlæstede og dræbte, var kanonkuglerne og geværkuglerne, som fløj over de marker, hvor mændene tumlede om. Så snart de slap ud af kugleregnen, samlede deres overordnede bag fronten dem igen og bragte dem under disciplin. I kraft af den disciplin førte de dem atter ind i ilden, hvor dødsangsten opløste disciplinen, og hvor enhver fór af sted, som mængden nu tilfældigvis rev ham med.')
d(226,26,'Militsfolkene bar fyrst Andrej hen til forbindingspladsen ved skoven, hvor vognene holdt. Tre telte med teltdugene slået til side var rejst i udkanten af en birkeskov. Inde mellem træerne stod vogne og heste. Hestene åd havre af deres løse krybber, og spurve slog ned og hakkede de korn i sig, som faldt på jorden. Nogle krager havde fået færten af blod og fløj utålmodigt skræppende mellem birkene. Omkring teltene, over et område på mere end to hektar, stod og sad og lå blodige mænd i alle slags klæder. Rundt om de sårede flokkedes bårebærerne med dystre, opmærksomme ansigter. Officererne, der skulle holde orden, forsøgte forgæves at jage dem væk. Soldaterne ænsede ikke ordrerne. De støttede sig til bårerne og stirrede ufravendt på det, der foregik for øjnene af dem, som prøvede de at løse en vanskelig gåde. Inde fra teltene lød snart høje, vrede råb, snart en klynkende stønnen. Af og til kom en sygehjælper løbende ud for at hente vand eller pege på den næste, der skulle bæres ind. De sårede, der ventede udenfor på deres tur, stønnede, sukkede, græd, skreg, bandede eller bad om vodka. Nogle talte i vildelse. De mænd, der bar fyrst Andrej, skrævede hen over de sårede, som endnu ikke var blevet forbundet. Da han var regimentschef, bar de ham helt hen til et af teltene. Der standsede de og ventede på besked. Fyrst Andrej slog øjnene op. Længe kunne han ikke forstå, hvad der foregik omkring ham. Han huskede engen, malurten, marken, den snurrende sorte kugle og den lidenskabelige kærlighed til livet, der pludselig var vældet op i ham. To skridt fra ham stod en høj, smuk, sorthåret underofficer med hovedet i bind. Han støttede sig til en gren og talte så højt, at alle lagde mærke til ham. Han var ramt af geværkugler i hovedet og benet. Omkring ham stod en flok sårede og bårebærere og lyttede ivrigt.')
